  function factOf(process2, code) {
    const table = PROC_FACT[process2] || PROC_FACT.Press;
    if (table[code]) {
      const [qty, defectRate2, uptimeRate2] = table[code];
      return { qty, defectRate: defectRate2, uptimeRate: uptimeRate2 };
    }
    let h = 0;
    for (let i2 = 0; i2 < code.length; i2 += 1) h = h * 31 + code.charCodeAt(i2) >>> 0;
    const rank = PRODUCTS.find((p) => p.code === code)?.rank || 50;
    const scale = Math.max(0.12, 1 - rank / 130);
    return {
      qty: Math.round((2e3 + h % 4200) * scale * 2.4),
      defectRate: Number((1.1 + (h >> 3) % 42 / 10).toFixed(1)),
      uptimeRate: 74 + (h >> 7) % 22
    };
  }

