  function rowsOf(processId, codes) {
    const list2 = (codes?.length ? codes : PRODUCTS.slice(0, 5).map((p) => p.code)).map((code) => {
      const p = PRODUCTS.find((x2) => x2.code === code) || { code, rank: 99, customer: "\u2014", project: "\u2014" };
      const f = factOf(processId, code);
      const ngQty = Math.round(f.qty * f.defectRate / 100);
      return {
        code,
        rank: p.rank,
        customer: p.customer,
        project: p.project,
        qty: f.qty,
        okQty: f.qty - ngQty,
        ngQty,
        defectRate: f.defectRate,
        yieldRate: Number((100 - f.defectRate).toFixed(1)),
        uptimeRate: f.uptimeRate
      };
    });
    return list2.sort((a, b) => a.rank - b.rank);
  }
  function summaryOf(processId, codes) {
    const rows2 = rowsOf(processId, codes);
    const qty = rows2.reduce((a, r) => a + r.qty, 0);
    const ngQty = rows2.reduce((a, r) => a + r.ngQty, 0);
    const defectRate2 = qty ? Number((ngQty / qty * 100).toFixed(1)) : 0;
    return {
      qty,
      okQty: qty - ngQty,
      ngQty,
      defectRate: defectRate2,
      yieldRate: Number((100 - defectRate2).toFixed(1)),
      avgUptime: rows2.length ? Math.round(rows2.reduce((a, r) => a + r.uptimeRate, 0) / rows2.length) : 0,
      productCnt: rows2.length
    };
  }
