      return ok(`${ver} \uB85C \uC804\uD658\uD588\uC2B5\uB2C8\uB2E4 \u2014 \uC790\uC5F0\uC5B4 \uC9C8\uC758\uAC00 \uC0C8 \uBC84\uC804\uC73C\uB85C \uC751\uB2F5\uD569\uB2C8\uB2E4.`, { ver });
